{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 9,
      "text_ar": "ولما كان إرميا يقول هذا عن ابن الله، بأنه آتي إلى العالم، غضب الشعب جداً وقالوا: \"هذا تكرار للكلام الذي نطق به إشعياء بن آموص، عندما قال: 'رأيت الله وابن الله'.\"",
      "verse": 21
    },
    {
      "chapter": 9,
      "text_ar": "هلموا إذن، ولنتجنب قتله بالطريقة التي قتلنا بها إشعياء، بل لنرجمه.",
      "verse": 22
    },
    {
      "chapter": 9,
      "text_ar": "وكان باروخ وأبيمالك حزينين جداً لأنهما أرادا أن يسمعا بالكامل الأسرار التي رأها.",
      "verse": 23
    },
    {
      "chapter": 9,
      "text_ar": "فقال لهما إرميا: \"اصمتا ولا تبكيا، لأنه لا يقدرون أن يقتلوني حتى أصف لكما كل ما رأيت.\"",
      "verse": 24
    },
    {
      "chapter": 9,
      "text_ar": "وقال لهما: \"ائتيا بحجر إلى هنا إليّ.\"",
      "verse": 25
    }
  ]
}
